            ByteBuffer queryBuffer = ByteBuffer.wrap(queryData);

            // Parse DNS Header
            int transactionId = queryBuffer.getShort() & 0xFFFF;
            int flags = queryBuffer.getShort() & 0xFFFF;
            int questionCount = queryBuffer.getShort() & 0xFFFF;
            int answerCount = queryBuffer.getShort() & 0xFFFF;
            int authorityCount = queryBuffer.getShort() & 0xFFFF;
            int additionalCount = queryBuffer.getShort() & 0xFFFF;

