            // Header
            responseBuffer.putShort((short) transactionId); // Transaction ID
            responseBuffer.putShort((short) 0x8180); // Flags: Standard query response, No error
            responseBuffer.putShort((short) 1); // Questions
            responseBuffer.putShort((short) 1); // Answer RRs
            responseBuffer.putShort((short) 0); // Authority RRs
            responseBuffer.putShort((short) 0); // Additional RRs

            // Question Section (echo back)
            byte[] domainBytes = domainName.toString().getBytes();
            String[] labels = domainName.toString().split("\\.");
