            responseBuffer.putShort((short) queryType);
            responseBuffer.putShort((short) queryClass);

            // Answer Section
            // Name (pointer to question)
            responseBuffer.putShort((short) 0xC00C);

            // Type A
            responseBuffer.putShort((short) 1);
            // Class IN
            responseBuffer.putShort((short) 1);
            // TTL (300 seconds)
            responseBuffer.putInt(300);
            // Data length (4 for IPv4)
            responseBuffer.putShort((short) 4);

