            byte[] ipBytes;
            try {
                InetAddress addr = InetAddress.getByName(domainName.toString());
                ipBytes = addr.getAddress();
            } catch (Exception e) {
                // Default to 127.0.0.1 if resolution fails
                ipBytes = new byte[]{127, 0, 0, 1};
            }
            responseBuffer.put(ipBytes);

            return Arrays.copyOf(responseBuffer.array(), responseBuffer.position());

        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static void sendResponse(DatagramSocket socket, InetAddress address, int port, byte[] responseData) {
        try {
            DatagramPacket response = new DatagramPacket(responseData, responseData.length, address, port);
            socket.send(response);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
